BEGIN;
CREATE TABLE flow_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),call_session_id uuid REFERENCES call_sessions(id),did_assignment_id uuid NOT NULL REFERENCES did_assignments(id),flow_id uuid NOT NULL REFERENCES flows(id),flow_version integer NOT NULL,current_node_id text NOT NULL,state text NOT NULL DEFAULT 'running' CHECK(state IN('running','waiting','completed','failed')),variables jsonb NOT NULL DEFAULT '{}'::jsonb,last_error text,started_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE flow_session_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),flow_session_id uuid NOT NULL REFERENCES flow_sessions(id) ON DELETE CASCADE,idempotency_key text NOT NULL,node_id text NOT NULL,node_type text NOT NULL,outcome text,action jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(flow_session_id,idempotency_key));
CREATE INDEX flow_sessions_active_idx ON flow_sessions(tenant_id,state,updated_at) WHERE state IN('running','waiting');
ALTER TABLE flow_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE flow_sessions FORCE ROW LEVEL SECURITY;ALTER TABLE flow_session_events ENABLE ROW LEVEL SECURITY;ALTER TABLE flow_session_events FORCE ROW LEVEL SECURITY;
CREATE POLICY flow_sessions_isolation ON flow_sessions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY flow_session_events_isolation ON flow_session_events USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
